diff --git a/search.mjs b/search.mjs
index bf487a7..c0a01ca 100644
--- a/search.mjs
+++ b/search.mjs
@@ -1,5 +1,25 @@
 // Isolated reproduction of article-search edge cases, not production code.
 export function searchArticles(rows, query) {
-  const needle = query.trim().toLowerCase();
-  return rows.filter(row => `${row.title || ''} ${row.summary || ''}`.toLowerCase().includes(needle));
+  const normalize = value => String(value ?? '').normalize('NFKC').toLowerCase();
+  const needle = normalize(query).trim();
+  if (!needle) return [];
+
+  const seen = new Set();
+  const results = [];
+  for (const row of rows) {
+    if (row === null || typeof row !== 'object' || Array.isArray(row)) continue;
+    if (typeof row.id !== 'string' || !row.id.trim()) continue;
+
+    const haystack = normalize(
+      [row.title, row.summary, row.title_zh, row.summary_zh]
+        .filter(value => typeof value === 'string')
+        .join(' ')
+    );
+    if (!haystack.includes(needle)) continue;
+    if (seen.has(row.id)) continue;
+
+    seen.add(row.id);
+    results.push(row);
+  }
+  return results;
 }
